import pandas as pd
import matplotlib.pyplot as plt
import glob
import os
import sys

# 1. Automatically load the latest time-series CSV generated by the new ns-3 code
csv_files = glob.glob('time_series_*.csv')
if not csv_files:
    print("Error: No 'time_series_*.csv' files found.")
    sys.exit()

latest_csv = max(csv_files, key=os.path.getmtime)
df = pd.read_csv(latest_csv)

# 2. Calculate the burst requests per interval
# Sum the cumulative requests across all servers, then find the difference between rows
df['Total_Cumulative'] = df['Server_1_Requests'] + df['Server_2_Requests'] + df['Server_3_Requests']
df['Requests'] = df['Total_Cumulative'].diff().fillna(0)

# 3. Create the plot
plt.figure(figsize=(10, 5))
plt.plot(df["Time_Seconds"], df["Requests"], color='blue', linewidth=1.5, marker='o', markersize=3)

# 4. Formatting
plt.title("Client Traffic Pattern (Burst Profile)", fontsize=14, fontweight='bold')
plt.xlabel("Simulation Time (Seconds)", fontsize=12)
plt.ylabel("Requests per 200ms", fontsize=12) # Updated to match your 0.2s logging interval
plt.grid(True, linestyle='--', alpha=0.7)
plt.xlim(0, 15) # Updated for the new 15-second simulation

# 5. Save the chart as an image
plt.tight_layout()
plt.savefig("traffic_pattern_chart.png", dpi=300)
print(f"Chart saved successfully as 'traffic_pattern_chart.png' (Read from {latest_csv})")
